import sys

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    try:
        n = int(input_data[0].strip())
    except ValueError:
        return

    lines = input_data[1:]

    for line in lines:
        if line.startswith("Simon says "):
            # Output the rest of the line starting from the character after "Simon says"
            # "Simon says" is 10 characters, plus the space is index 10 to 10 (inclusive)
            # So we slice from index 11
            print(line[11:])

if __name__ == "__main__":
    main()
